// @pit: {"label": "Commit version bump, push, and open the release 2.5.0 pull request"}
async ({ shell: { execFile } }, p: { body: string }) => {
  const r = (a: string[]) => execFile(a[0], a.slice(1), { raise: true });
  await r(["git", "commit", "-am", "chore: release 2.5.0"]);
  await r(["git", "push", "-u", "origin", "chore/release-2.5.0"]);
  const pr = await r(["gh", "pr", "create", "--base", "main", "--head", "chore/release-2.5.0", "--title", "chore: release 2.5.0", "--body", p.body]);
  return pr.stdout + pr.stderr;
}
